    /// Set param `playing` (bool); false = rejected by the kernel.
    pub fn set_playing(&mut self, v: bool) -> bool {
        let mut pv = ParamValue {
            kind: 4,
            num: 0.0,
            s: String::new(),
            rgba: 0,
            sym: String::new(),
        };
        pv.num = if v { 1.0 } else { 0.0 };
        kframe::inst_set_param(&mut self.inst, 5, &pv)
    }
